pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let input_map = input.as_object().expect("Input must be an object");
    let shift = input_map
        .get("shift")
        .and_then(|v| v.as_i64())
        .expect("Input must have a 'shift' field");
    let text = input_map
        .get("text")
        .and_then(|v| v.as_str())
        .expect("Input must have a 'text' field");

    let mut result = String::new();
    for c in text.chars() {
        if c >= 'a' && c <= 'z' {
            let shifted = ((c as u8 - b'a' + shift as u8) % 26) as u8;
            result.push((b'a' + shifted) as char);
        } else {
            result.push(c);
        }
    }

    serde_json::json!(result)
}
